import math

def earliest_arrival(n: int, connections: list[tuple[int, int, int, int]], source: int, target: int, start: int, change: int, max_transfers: int) -> int:
    if source == target:
        return start

    INF = 10**18  # 時刻は最大 10^9 なので、十分大きな値を使用

    # 1. 接続情報の構造化 (adj[u] = リスト of (v, depart, arrive))
    adj = [[] for _ in range(n)]
    for u, v, depart, arrive in connections:
        # u から v への便情報を格納
        adj[u].append((v, depart, arrive))

    # dp[k][u]: k 回乗り換え後に駅 u に到達する最小到着時刻
    # k は 0 から max_transfers まで
    dp = [[INF] * n for _ in range(max_transfers + 1)]

    # 2. ベースケース k=0 (乗車本数 1, 乗り換え 0回)
    # 初期待機時刻 start から source から出る最初の便に乗る
    T_start = start

    for v, depart, arrive in adj[source]:
        if T_start <= depart:
            dp[0][v] = min(dp[0][v], arrive)

    # 3. DP遷移 k=1 から max_transfers
    for k in range(1, max_transfers + 1):
        # k-1 回の乗り換え後の到達時刻 dp[k-1][v] を利用する
        for v in range(n):
            T_v = dp[k-1][v]

            # v に到達できていない場合はスキップ
            if T_v == INF:
                continue

            # v から出る全ての便 (u, depart, arrive) を考える
            for u, depart, arrive in adj[v]:
                # 乗り換え条件: T_v + change <= depart
                if T_v + change <= depart:
                    new_arrival_time = arrive
                    dp[k][u] = min(dp[k][u], new_arrival_time)

    # 4. 結果の抽出
    min_arrival = INF
    for k in range(max_transfers + 1):
        min_arrival = min(min_arrival, dp[k][target])

    if min_arrival == INF:
        return -1
    else:
        return min_arrival
